const fs=require('node:fs');const assert=require('node:assert/strict');const {chromium}=require('C:/Users/Administrator/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');let count=0;const pass=s=>{count++;console.log('PASS '+s)};
(async()=>{const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});const page=await browser.newPage({viewport:{width:1440,height:1100}});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.route(/fonts\.(googleapis|gstatic)\.com/,r=>r.abort());try{
await page.goto('http://localhost:4173/tank.html');await page.waitForFunction(()=>window.PixelTank);assert.equal(await page.locator('#roster1 button').count(),6);assert.equal(await page.locator('#roster2 button').count(),6);pass('six original characters available to both players');
await page.locator('#roster1 button[data-id=goku]').click();await page.selectOption('#mode','coop');await page.locator('#roster2 button[data-id=nezha]').click();await page.click('#start');await page.waitForFunction(()=>PixelTank.snapshot?.phase==='playing');assert.deepEqual(await page.evaluate(()=>PixelTank.snapshot.players.map(p=>p.id)),['goku','nezha']);pass('cooperative game starts with selected characters');
await page.evaluate(()=>{const b=PixelTank.battle;b.paused=true;b.queue=['boss','armor'];b.spawn();b.spawn();for(const e of b.enemies)e.shield=8;b.drop(b.players[1].x,b.players[1].y-40,'bomb');});await page.waitForTimeout(80);await page.locator('#battle').screenshot({path:'preview-tank-bomb.png'});const cleared=await page.evaluate(()=>{const b=PixelTank.battle,p=b.players[1],item=b.pickups.find(i=>i.type==='bomb');item.x=p.x;item.y=p.y;b.paused=false;b.spawnClock=999;b.step(1/60);b.paused=true;return {remaining:b.enemies.length,kills:b.kills,score:p.score,flash:b.bombFlash,boss:b.enemies[0]?.type,bossHp:b.enemies[0]?.hp};});assert.equal(cleared.remaining,1);assert.equal(cleared.boss,'boss');assert.equal(cleared.bossHp,14);assert.equal(cleared.kills,1);assert.equal(cleared.score,300);assert(cleared.flash>0);await page.evaluate(()=>PixelTank.battle.paused=false);pass('bomb icon renders and player-two collision clears shielded armor while preserving boss');
await page.keyboard.down('KeyJ');await page.waitForTimeout(80);assert.equal(await page.evaluate(()=>PixelTank.input(0).fire),true);assert(await page.evaluate(()=>PixelTank.battle.shots.some(s=>s.owner===PixelTank.battle.players[0].uid)));await page.keyboard.up('KeyJ');await page.keyboard.down('Enter');await page.waitForTimeout(80);assert(await page.evaluate(()=>PixelTank.battle.shots.some(s=>s.owner===PixelTank.battle.players[1].uid)));await page.keyboard.up('Enter');pass('real keyboard fire works independently for both players');
const x=await page.evaluate(()=>PixelTank.battle.players[0].x);await page.keyboard.down('KeyD');await page.waitForTimeout(300);await page.keyboard.up('KeyD');assert((await page.evaluate(()=>PixelTank.battle.players[0].x))>x+15);const qx=await page.evaluate(()=>PixelTank.battle.players[1].y);await page.keyboard.down('ArrowUp');await page.waitForTimeout(300);await page.keyboard.up('ArrowUp');assert((await page.evaluate(()=>PixelTank.battle.players[1].y))<qx-15);pass('both players move with their own directional controls');
await page.keyboard.press('KeyK');await page.waitForTimeout(100);assert((await page.evaluate(()=>PixelTank.battle.players[0].energy))<10);await page.keyboard.press('ShiftRight');await page.waitForTimeout(100);assert((await page.evaluate(()=>PixelTank.battle.players[1].haste))>4);pass('both special abilities activate with separate keys');
await page.keyboard.press('KeyP');assert(await page.evaluate(()=>PixelTank.snapshot.paused));const before=await page.evaluate(()=>JSON.stringify(PixelTank.snapshot));await page.waitForTimeout(250);assert.equal(await page.evaluate(()=>JSON.stringify(PixelTank.snapshot)),before);await page.click('#resume');assert.equal(await page.evaluate(()=>PixelTank.snapshot.paused),false);pass('pause freezes simulation and resume restores it');
await page.screenshot({path:'preview-tank-battle.png',fullPage:true});await page.keyboard.press('Escape');await page.click('#choose');await page.selectOption('#mode','solo');for(const id of ['explorer','soldier','mystic','dora','goku','nezha']){await page.locator('#roster1 button[data-id='+id+']').click();assert.equal(await page.evaluate(()=>PixelTank.pick.p1),id)}pass('all six tank and character previews render without errors');
await page.selectOption('#level','2');await page.click('#start');await page.waitForFunction(()=>PixelTank.snapshot.phase==='playing');await page.evaluate(()=>{const b=PixelTank.battle;b.queue=['boss'];b.enemies=[];b.spawnClock=0});await page.waitForFunction(()=>PixelTank.battle.enemies.some(e=>e.type==='boss'));assert((await page.evaluate(()=>PixelTank.battle.enemies[0].maxHp))>=18);pass('boss spawns in a playable boss stage');
await page.evaluate(()=>{const b=PixelTank.battle;b.queue=[];b.enemies=[]});await page.waitForFunction(()=>PixelTank.snapshot.phase==='clear');await page.waitForFunction(()=>PixelTank.snapshot.level===3);pass('stage clear automatically loads the next map');
await page.evaluate(()=>{const b=PixelTank.battle;b.load(5);b.phase='playing';b.queue=[];b.enemies=[]});await page.waitForFunction(()=>PixelTank.snapshot.phase==='victory');assert.equal(await page.locator('#modal-title').textContent(),'VICTORY!');assert.equal(await page.locator('#resume').isVisible(),false);pass('final clear displays victory and restart controls');
await page.click('#choose');await page.setViewportSize({width:390,height:844});await page.selectOption('#mode','coop');await page.locator('#start').scrollIntoViewIfNeeded();assert(await page.locator('#start').isVisible());assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.screenshot({path:'preview-tank-mobile.png',fullPage:true});await page.click('#start');await page.waitForFunction(()=>PixelTank.snapshot.phase==='playing');await page.keyboard.press('Escape');await page.locator('#resume').scrollIntoViewIfNeeded();await page.click('#resume');assert.equal(await page.evaluate(()=>PixelTank.snapshot.paused),false);pass('mobile setup, layout and pause buttons remain usable');
await page.setViewportSize({width:1440,height:1100});await page.goto('http://localhost:4173/');await page.waitForFunction(()=>window.PixelQuest);assert.equal(await page.locator('#play-kart').count(),0);assert(await page.locator('[data-launch=play-tank]').isVisible());assert.equal(await page.locator('#play-fighting').count(),1);await page.locator('[data-launch=play-tank]').click();await page.waitForURL('**/tank.html');await page.waitForFunction(()=>window.PixelTank);assert.equal(await page.evaluate(()=>typeof PixelQuest),'undefined');assert.equal(await page.evaluate(()=>typeof PixelFighting),'undefined');pass('main menu opens independent tank mode and retains other entries');
await page.goto('http://localhost:4173/kart.html');await page.waitForURL('**/tank.html');pass('retired kart URL redirects to tank battle');
await page.goto('http://localhost:4173/badminton.html');await page.waitForFunction(()=>window.PixelBadminton);assert.equal(await page.locator('a[href$="tank.html"]').count(),0);assert.equal(await page.locator('#bd-characters button').count(),6);assert.equal(await page.locator('a.brand').count(),1);pass('badminton still loads six characters and returns to the lobby');
await page.goto('http://localhost:4173/fighting.html');await page.waitForFunction(()=>window.PixelFighting);pass('existing fighting mode still initializes');
const phone=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});phone.on('pageerror',e=>errors.push(e.message));await phone.goto('http://localhost:4173/tank.html');await phone.locator('#start').tap();await phone.waitForFunction(()=>PixelTank.snapshot.phase==='playing');await phone.locator('[data-key="KeyK"]').tap();await phone.waitForTimeout(100);assert((await phone.evaluate(()=>PixelTank.battle.players[0].energy))<10);assert(await phone.locator('[data-key="KeyJ"]').isVisible());await phone.locator('[data-key="KeyJ"]').tap();await phone.waitForTimeout(100);assert(await phone.evaluate(()=>PixelTank.battle.shots.some(s=>s.friendly&&!s.special)));await phone.close();pass('actual touch taps activate special and ordinary fire');
assert.deepEqual(errors,[]);pass('no JavaScript runtime errors across tested modes');console.log(count+' Tank Battle browser checks passed');}finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
